const blankMember = { fullName: '', preferredName: '', nickname: '', gender: '', birthDate: '', deathDate: '', hometown: '', occupation: '', phone: '', email: '', address: '', social: '', notes: '', archived: false, avatarDataUrl: '' }
function FamilyTreeNode({ data }) { return <><Handle type="target" id="top" position={Position.Top} className="tree-handle" /><Handle type="source" id="top-source" position={Position.Top} className="tree-handle" /><Handle type="target" id="bottom-target" position={Position.Bottom} className="tree-handle" /><Handle type="source" id="bottom" position={Position.Bottom} className="tree-handle" /><Handle type="target" id="left" position={Position.Left} className="tree-handle" /><Handle type="source" id="left-source" position={Position.Left} className="tree-handle" /><Handle type="target" id="right" position={Position.Right} className="tree-handle" /><Handle type="source" id="right" position={Position.Right} className="tree-handle" />{data.label}</> }
const FAMILY_NODE_TYPES = { familyMember: FamilyTreeNode }
function ReactFlow({ nodes, edges, ...props }) { const positions = Object.fromEntries(nodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const isSpouse = edge.animated || ['spouse', 'wife', 'husband', 'partner'].includes(String(edge.label || '').trim().toLowerCase()); if (!isSpouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top', style: { ...edge.style, strokeWidth: 2.5 } }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', animated: true, sourceHandle: sourceLeft ? 'right' : 'left', targetHandle: sourceLeft ? 'left' : 'right', style: { ...edge.style, strokeWidth: 3 } } }); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={nodes} edges={routedEdges} nodeTypes={{ default: FamilyTreeNode }} onEdgeClick={openRelation} /> }
function DraggableReactFlow({ nodes, edges, ...props }) { const positions = Object.fromEntries(nodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left', targetHandle: sourceLeft ? 'left' : 'right' } }); const persistPosition = (_, node) => window.dispatchEvent(new CustomEvent('move-family-member', { detail: { id: node.id, position: node.position } })); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={nodes} edges={routedEdges} nodeTypes={{ default: FamilyTreeNode }} nodesDraggable onNodeDragStop={persistPosition} onEdgeClick={openRelation} /> }
ReactFlow = DraggableReactFlow
function FullyDraggableReactFlow({ nodes, edges, ...props }) { const [localNodes, setLocalNodes] = useState(nodes); useEffect(() => setLocalNodes(nodes), [nodes]); const positions = Object.fromEntries(localNodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left', targetHandle: sourceLeft ? 'left' : 'right' } }); const persistPosition = (_, node) => window.dispatchEvent(new CustomEvent('move-family-member', { detail: { id: node.id, position: node.position } })); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={localNodes.map((node) => ({ ...node, draggable: true }))} edges={routedEdges} nodeTypes={{ default: FamilyTreeNode }} nodesDraggable onNodesChange={(changes) => setLocalNodes((current) => applyNodeChanges(changes, current))} onNodeDragStop={persistPosition} onEdgeClick={openRelation} /> }
ReactFlow = FullyDraggableReactFlow
function StableFamilyTreeFlow({ nodes, edges, ...props }) { const [localNodes, setLocalNodes] = useState(nodes); useEffect(() => setLocalNodes(nodes), [nodes]); const positions = Object.fromEntries(localNodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left', targetHandle: sourceLeft ? 'left' : 'right' } }); const persistPosition = (_, node) => window.dispatchEvent(new CustomEvent('move-family-member', { detail: { id: node.id, position: node.position } })); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={localNodes.map((node) => ({ ...node, draggable: true }))} edges={routedEdges} nodeTypes={FAMILY_NODE_TYPES} nodesDraggable onNodesChange={(changes) => setLocalNodes((current) => applyNodeChanges(changes, current))} onNodeDragStop={persistPosition} onEdgeClick={openRelation} /> }
ReactFlow = StableFamilyTreeFlow
function CorrectedFamilyTreeFlow({ nodes, edges, ...props }) { const [localNodes, setLocalNodes] = useState(nodes); useEffect(() => setLocalNodes(nodes), [nodes]); const renderedNodes = localNodes.map((node) => ({ ...node, type: 'familyMember', draggable: true })); const positions = Object.fromEntries(renderedNodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left', targetHandle: sourceLeft ? 'left' : 'right' } }); const persistPosition = (_, node) => window.dispatchEvent(new CustomEvent('move-family-member', { detail: { id: node.id, position: node.position } })); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={renderedNodes} edges={routedEdges} nodeTypes={FAMILY_NODE_TYPES} nodesDraggable onNodesChange={(changes) => setLocalNodes((current) => applyNodeChanges(changes, current))} onNodeDragStop={persistPosition} onEdgeClick={openRelation} /> }
ReactFlow = CorrectedFamilyTreeFlow
function FinalFamilyTreeFlow({ nodes, edges, ...props }) { const [localNodes, setLocalNodes] = useState(nodes); useEffect(() => setLocalNodes(nodes), [nodes]); const renderedNodes = localNodes.map((node) => ({ ...node, type: 'familyMember', draggable: true })); const positions = Object.fromEntries(renderedNodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left-source', targetHandle: sourceLeft ? 'left' : 'right' } }); const persistPosition = (_, node) => window.dispatchEvent(new CustomEvent('move-family-member', { detail: { id: node.id, position: node.position } })); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={renderedNodes} edges={routedEdges} nodeTypes={FAMILY_NODE_TYPES} nodesDraggable onNodesChange={(changes) => setLocalNodes((current) => applyNodeChanges(changes, current))} onNodeDragStop={persistPosition} onEdgeClick={openRelation} /> }
ReactFlow = FinalFamilyTreeFlow
function ReconnectableFamilyTreeFlow({ nodes, edges, ...props }) { const [localNodes, setLocalNodes] = useState(nodes); const [localEdges, setLocalEdges] = useState(edges); useEffect(() => setLocalNodes(nodes), [nodes]); useEffect(() => setLocalEdges(edges), [edges]); const renderedNodes = localNodes.map((node) => ({ ...node, type: 'familyMember', draggable: true })); const positions = Object.fromEntries(renderedNodes.map((node) => [node.id, node.position])); const routedEdges = localEdges.map((edge) => { if (edge.sourceHandle && edge.targetHandle) return edge; const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left-source', targetHandle: sourceLeft ? 'left' : 'right' } }); const persistPosition = (_, node) => window.dispatchEvent(new CustomEvent('move-family-member', { detail: { id: node.id, position: node.position } })); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={renderedNodes} edges={routedEdges} nodeTypes={FAMILY_NODE_TYPES} nodesDraggable edgesReconnectable onNodesChange={(changes) => setLocalNodes((current) => applyNodeChanges(changes, current))} onReconnect={(oldEdge, connection) => setLocalEdges((current) => reconnectEdge(oldEdge, connection, current))} onNodeDragStop={persistPosition} onEdgeClick={openRelation} /> }
ReactFlow = ReconnectableFamilyTreeFlow
function FixedFamilyTreeFlow({ nodes, edges, ...props }) { const renderedNodes = nodes.map((node) => ({ ...node, type: 'familyMember', draggable: false })); const positions = Object.fromEntries(renderedNodes.map((node) => [node.id, node.position])); const routedEdges = edges.map((edge) => { const spouse = edge.animated || String(edge.label || '').trim().toLowerCase() === 'spouse'; if (!spouse) return { ...edge, type: 'straight', sourceHandle: 'bottom', targetHandle: 'top' }; const sourceLeft = (positions[edge.source]?.x || 0) < (positions[edge.target]?.x || 0); return { ...edge, type: 'straight', sourceHandle: sourceLeft ? 'right' : 'left-source', targetHandle: sourceLeft ? 'left' : 'right' } }); const openRelation = (event, edge) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('open-relationship-detail', { detail: edge.id })) }; return <ReactFlowBase {...props} nodes={renderedNodes} edges={routedEdges} nodeTypes={FAMILY_NODE_TYPES} nodesDraggable={false} onEdgeClick={openRelation} /> }
ReactFlow = FixedFamilyTreeFlow
function Avatar({ member, large = false }) { return member?.avatarDataUrl ? <img className={`avatar ${large ? 'large' : ''}`} src={member.avatarDataUrl} alt="" /> : <span className={`avatar fallback ${large ? 'large' : ''}`}>{initials(member?.preferredName || member?.fullName)}</span> }
function App() {
  const [user, setUser] = useState(undefined); const [authError, setAuthError] = useState('')
  useEffect(() => { if (!firebaseReady) { setUser(null); return } return onAuthStateChanged(auth, setUser) }, [])
  if (user === undefined) return <Loading label="Opening your family album…" />
  if (!firebaseReady) return <SetupNeeded />
  if (!isAllowedUser(user)) return <SignIn error={authError} setError={setAuthError} />
  return <><Routes><Route path="/" element={<Dashboard user={user} />} /><Route path="/tree/:groupId" element={<TreePage user={user} />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes><RelationshipOverlay /><RelationshipDetailOverlay /><PositionPersistence /></>
}
function SignIn({ error, setError }) { const login = async () => { try { setError(''); const result = await signInWithPopup(auth, googleProvider); if (!isAllowedUser(result.user)) { await signOut(auth); setError('This family album is private. Please use the approved Google account.') } } catch (e) { setError(e.code === 'auth/popup-closed-by-user' ? 'Sign-in was cancelled.' : 'Google sign-in could not be completed. Please try again.') } }; return <main className="auth"><div className="auth-card"><span className="sun">✦</span><p className="eyebrow">PRIVATE FAMILY ALBUM</p><h1>Our roots,<br /><i>together.</i></h1><p>Keep every generation, story, and familiar face close at hand.</p>{error && <p className="error">{error}</p>}<button className="primary" onClick={login}>Continue with Google</button><small>Access is reserved for the family administrator.</small></div></main> }
function SetupNeeded() { return <main className="auth"><div className="auth-card"><p className="eyebrow">CONFIGURATION REQUIRED</p><h1>Almost ready.</h1><p>Add your Firebase Web App values to <code>.env</code>, then restart Vite.</p><p className="hint">See README.md for the one-time Firebase setup.</p></div></main> }
function Header({ user, back }) { const nav = useNavigate(); return <header><button className="brand" onClick={() => nav('/')}><span>✦</span> Our Family</button>{back && <button className="text-button" onClick={() => nav('/')}><ChevronLeft size={18} /> All families</button>}<div className="header-user"><span>{user.displayName?.split(' ')[0]}</span><button aria-label="Sign out" className="icon-button" onClick={() => signOut(auth)}><LogOut size={18} /></button></div></header> }
function Dashboard({ user }) { const [groups, setGroups] = useState([]); const [loading, setLoading] = useState(true); const [editing, setEditing] = useState(null); const refresh = async () => { setLoading(true); try { setGroups(await listGroups()) } finally { setLoading(false) } }; useEffect(() => { refresh() }, []); return <><Header user={user} /><main className="shell"><section className="hero"><div><p className="eyebrow">FAMILY ARCHIVE</p><h1>A living map of<br /><i>the people you love.</i></h1><p>Build separate branches for every side of your family, one story at a time.</p></div><button className="primary" onClick={() => setEditing({})}><Plus size={18} /> New family branch</button></section><section><div className="section-title"><h2>Your family branches</h2><span>{groups.length} total</span></div>{loading ? <Loading label="Gathering branches…" /> : groups.length ? <div className="group-grid">{groups.map((group) => <motion.article whileHover={{ y: -4 }} key={group.id} className="group-card" style={{ '--cover': group.coverColor || '#f47c3c' }}><span className="group-mark">✦</span><p className="eyebrow">FAMILY BRANCH</p><h3>{group.name}</h3><p>{group.description || 'A place for shared stories and generations.'}</p><div><button className="text-button" onClick={() => setEditing(group)}><Pencil size={16} /> Edit</button><a className="card-link" href={`#/tree/${group.id}`}>Open tree →</a></div></motion.article>)}</div> : <Empty onClick={() => setEditing({})} />}</section></main><AnimatePresence>{editing && <GroupDialog group={editing} done={() => { setEditing(null); refresh() }} />}</AnimatePresence></> }
function GroupDialog({ group, done }) { const [form, setForm] = useState({ name: group.name || '', description: group.description || '', coverColor: group.coverColor || '#f47c3c' }); const [busy, setBusy] = useState(false); const submit = async (e) => { e.preventDefault(); if (!form.name.trim()) return; setBusy(true); await saveGroup(form, group.id); done() }; const remove = async () => { if (group.id && confirm(`Delete ${group.name} and all its members? This cannot be undone.`)) { setBusy(true); await removeGroup(group.id); done() } }; return <Dialog title={group.id ? 'Edit family branch' : 'Create a family branch'} close={done}><form onSubmit={submit} className="form"><label>Branch name<input autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Patel paternal family" /></label><label>Description<textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="A short note about this branch" /></label><label>Cover colour<input type="color" value={form.coverColor} onChange={(e) => setForm({ ...form, coverColor: e.target.value })} /></label><div className="dialog-actions">{group.id && <button type="button" className="danger" onClick={remove}>Delete branch</button>}<button className="primary" disabled={busy}>{busy ? 'Saving…' : 'Save branch'}</button></div></form></Dialog> }
function PersonBranchDialog({ group, done }) {
  const [form, setForm] = useState({ personName: group.rootPersonName || '', location: '', description: group.description || '', coverColor: group.coverColor || '#f47c3c' })
  const [busy, setBusy] = useState(false)
  const submit = async (event) => { event.preventDefault(); if (!form.personName.trim()) return; setBusy(true); try { if (group.id) { await saveGroup({ name: group.name, rootPersonName: form.personName, description: form.description, coverColor: form.coverColor }, group.id) } else { const branch = await saveGroup({ name: `${form.personName.trim()}'s family`, rootPersonName: form.personName.trim(), description: form.description, coverColor: form.coverColor }); const root = await saveMember({ fullName: form.personName.trim(), hometown: form.location.trim(), familyGroupId: branch.id, isRootPerson: true, archived: false }); await saveGroup({ rootMemberId: root.id }, branch.id) } done() } finally { setBusy(false) } }
  const remove = async () => { if (group.id && confirm(`Delete ${group.name} and all people in this family branch?`)) { setBusy(true); await removeGroup(group.id); done() } }
  return <Dialog title={group.id ? 'Edit person branch' : 'Start a person’s family tree'} close={done}><form onSubmit={submit} className="form"><p className="hint">This branch contains one person’s parents, spouse, children, and both sides of their extended family.</p><label>Primary person’s full name *<input autoFocus required value={form.personName} onChange={(e) => setForm({ ...form, personName: e.target.value })} placeholder="e.g. Prashant Patel" /></label>{!group.id && <label>Location <input value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} placeholder="Optional" /></label>}<label>Branch note<textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Optional family note" /></label><label>Cover colour<input type="color" value={form.coverColor} onChange={(e) => setForm({ ...form, coverColor: e.target.value })} /></label><div className="dialog-actions">{group.id && <button type="button" className="danger" onClick={remove}>Delete branch</button>}<button className="primary" disabled={busy}>{busy ? 'Saving…' : group.id ? 'Save branch' : 'Create family tree'}</button></div></form></Dialog> }
// A branch always starts with one primary person; every other member belongs through a direct relationship.
GroupDialog = PersonBranchDialog
function TreePage({ user }) { const { groupId } = useParams(); const [data, setData] = useState({ members: [], relationships: [] }); const [loading, setLoading] = useState(true); const [selected, setSelected] = useState(null); const [form, setForm] = useState(null); const [query, setQuery] = useState(''); const refresh = async () => { setLoading(true); try { setData(await loadGroupData(groupId)) } finally { setLoading(false) } }; useEffect(() => { refresh() }, [groupId]); const members = data.members.filter((m) => !m.archived && `${m.fullName} ${m.nickname}`.toLowerCase().includes(query.toLowerCase())); const nodes = useMemo(() => layoutMembers(members, data.relationships).map((m) => ({ id: m.id, position: m.position, data: { label: <MemberCard member={m} /> }, style: { border: 0, background: 'transparent', width: 200 }, sourcePosition: 'bottom', targetPosition: 'top' })), [members, data.relationships]); const edges = data.relationships.filter((r) => members.some((m) => m.id === r.fromMemberId) && members.some((m) => m.id === r.toMemberId)).map((r) => ({ id: r.id, source: r.fromMemberId, target: r.toMemberId, animated: r.type === 'spouse', label: r.label || (r.type === 'spouse' ? 'spouse' : ''), style: { stroke: '#d79a73' } })); return <><Header user={user} back /><main className="tree-page"><div className="tree-toolbar"><div><p className="eyebrow">INTERACTIVE TREE</p><h2>Family branch</h2></div><div className="toolbar-actions"><label className="search"><Search size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Find a person" /></label><button className="primary" onClick={() => setForm({ member: null })}><Plus size={17} /> Add member</button></div></div>{loading ? <Loading label="Growing your tree…" /> : !data.members.filter((m) => !m.archived).length ? <Empty onClick={() => setForm({ member: null })} text="Start this branch by adding its first family member." /> : <div className="tree-canvas"><ReactFlow nodes={nodes} edges={edges} onNodeClick={(_, node) => setSelected(data.members.find((m) => m.id === node.id))} fitView minZoom={0.15} maxZoom={2} nodesDraggable={false}><Background color="#ead8ca" gap={22} /><Controls /><MiniMap pannable zoomable /></ReactFlow></div>}<section className="directory"><div className="section-title"><h2>Family directory</h2><span>{data.members.filter((m) => !m.archived).length} people</span></div><div className="directory-grid">{members.map((member) => <button key={member.id} className="directory-person" onClick={() => setSelected(member)}><Avatar member={member} /><span><b>{member.preferredName || member.fullName}</b><small>{member.nickname && `“${member.nickname}”`}</small></span></button>)}</div></section></main><AnimatePresence>{selected && <Profile member={selected} relationships={data.relationships} members={data.members} close={() => setSelected(null)} edit={() => { setSelected(null); setForm({ member: selected }) }} />}{form && <MemberDialog member={form.member} groupId={groupId} members={data.members.filter((m) => !m.archived)} done={() => { setForm(null); refresh() }} />}</AnimatePresence></> }
function MemberCard({ member }) { const addRelated = (event) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent('add-related-member', { detail: { member } })) }; return <div className={`node-card ${member.isRootPerson ? 'self-node' : ''} ${member.isVoid ? 'void-node' : ''}`}><button className="add-relation-dot top" title={`Add a relation to ${member.fullName}`} onClick={addRelated}>+</button><Avatar member={member} /><div><b>{member.isVoid ? 'Void' : member.preferredName || member.fullName}</b>{member.isVoid && <small>Removed family member</small>}{member.isRootPerson && !member.isVoid && <span className="self-chip">Self</span>}{member.nickname && <small>“{member.nickname}”</small>}</div><button className="add-relation-dot bottom" title={`Add a relation to ${member.fullName}`} onClick={addRelated}>+</button></div> }
function Profile({ member, relationships, members, close, edit }) { const linked = relationships.filter((r) => r.fromMemberId === member.id || r.toMemberId === member.id).map((r) => ({ person: members.find((m) => m.id === (r.fromMemberId === member.id ? r.toMemberId : r.fromMemberId)), label: r.label })).filter((item) => item.person); return <motion.aside className="profile" initial={{ x: 360 }} animate={{ x: 0 }} exit={{ x: 360 }}><button className="close" onClick={close}><X /></button><Avatar member={member} large /><p className="eyebrow">{member.isRootPerson ? 'SELF · PRIMARY PERSON' : 'FAMILY MEMBER'}</p><h2>{member.preferredName || member.fullName}</h2>{member.nickname && <p className="nickname">“{member.nickname}”</p>}<dl>{member.birthDate && <><dt>Born</dt><dd>{new Date(`${member.birthDate}T00:00`).toLocaleDateString(undefined, { dateStyle: 'long' })}</dd></>}{member.hometown && <><dt>Hometown</dt><dd>{member.hometown}</dd></>}{member.occupation && <><dt>Occupation</dt><dd>{member.occupation}</dd></>}{member.phone && <><dt>Phone</dt><dd><a href={`tel:${member.phone}`}>{member.phone}</a></dd></>}{member.email && <><dt>Email</dt><dd><a href={`mailto:${member.email}`}>{member.email}</a></dd></>}{member.address && <><dt>Address</dt><dd>{member.address}</dd></>}</dl>{member.notes && <p className="notes">{member.notes}</p>}{linked.length > 0 && <><h3>Connected family</h3><div className="linked">{linked.map(({ person, label }) => <span key={person.id}><Avatar member={person} /> {person.preferredName || person.fullName}{label && <small> · {label}</small>}</span>)}</div></>}<button className="primary full" onClick={edit}><Pencil size={16} /> Edit profile</button></motion.aside> }
function ProfileWithRelationshipActions({ member, relationships, members, close, edit }) { const [removing, setRemoving] = useState(''); const linked = relationships.filter((relationship) => relationship.fromMemberId === member.id || relationship.toMemberId === member.id).map((relationship) => ({ relationship, person: members.find((person) => person.id === (relationship.fromMemberId === member.id ? relationship.toMemberId : relationship.fromMemberId)) })).filter((item) => item.person); const remove = async (item) => { if (!confirm(`Remove the relationship with ${item.person.fullName}?`)) return; setRemoving(item.relationship.id); await deleteRelationship(item.relationship.id); window.location.reload() }; return <motion.aside className="profile" initial={{ x: 360 }} animate={{ x: 0 }} exit={{ x: 360 }}><button className="close" onClick={close}><X /></button><Avatar member={member} large /><p className="eyebrow">{member.isRootPerson ? 'SELF · PRIMARY PERSON' : 'FAMILY MEMBER'}</p><h2>{member.preferredName || member.fullName}</h2>{member.nickname && <p className="nickname">“{member.nickname}”</p>}<dl>{member.hometown && <><dt>Location</dt><dd>{member.hometown}</dd></>}{member.occupation && <><dt>Occupation</dt><dd>{member.occupation}</dd></>}{member.phone && <><dt>Phone</dt><dd>{member.phone}</dd></>}</dl>{linked.length > 0 && <><h3>Relationships</h3><div className="linked relationship-list">{linked.map((item) => <span key={item.relationship.id}><Avatar member={item.person} /><b>{item.person.preferredName || item.person.fullName}</b><small>{item.relationship.label || item.relationship.type}</small><button className="remove-relation" disabled={removing === item.relationship.id} onClick={() => remove(item)}>Remove</button></span>)}</div></>}<button className="primary full" onClick={edit}><Pencil size={16} /> Edit profile</button></motion.aside> }
