function ProfileWithVoidAction({ member, relationships, members, close, edit }) { const linked = relationships.filter((relationship) => relationship.fromMemberId === member.id || relationship.toMemberId === member.id).map((relationship) => ({ relationship, person: members.find((person) => person.id === (relationship.fromMemberId === member.id ? relationship.toMemberId : relationship.fromMemberId)) })).filter((item) => item.person); const remove = async (item) => { if (confirm(`Remove the relationship with ${item.person.fullName}?`)) { await deleteRelationship(item.relationship.id); window.location.reload() } }; const removeMember = async () => { if (confirm(`Delete ${member.fullName}? Their descendants and relationships will remain connected through a Void node.`)) { await voidMember(member.id); window.location.reload() } }; return <motion.aside className="profile" initial={{ x: 360 }} animate={{ x: 0 }} exit={{ x: 360 }}><button className="close" onClick={close}><X /></button><Avatar member={member} large /><p className="eyebrow">{member.isVoid ? 'VOID NODE' : member.isRootPerson ? 'SELF · PRIMARY PERSON' : 'FAMILY MEMBER'}</p><h2>{member.isVoid ? 'Void' : member.preferredName || member.fullName}</h2>{!member.isVoid && member.hometown && <p className="hint">{member.hometown}</p>}{linked.length > 0 && <><h3>Relationships</h3><div className="linked relationship-list">{linked.map((item) => <span key={item.relationship.id}><Avatar member={item.person} /><b>{item.person.isVoid ? 'Void' : item.person.preferredName || item.person.fullName}</b><small>{item.relationship.label || item.relationship.type}</small><button className="remove-relation" onClick={() => remove(item)}>Remove</button></span>)}</div></>}{!member.isVoid && <><button className="primary full" onClick={edit}><Pencil size={16} /> Edit profile</button><button className="delete-member" onClick={removeMember}>Delete member — keep Void node</button></>}</motion.aside> }
