function ProfileWithKinship({ member, relationships, members, close, edit }) { const root = members.find((person) => person.isRootPerson && !person.isVoid); const kinship = inferKinship(root?.id, member.id, members, relationships); const linked = relationships.filter((relationship) => relationship.fromMemberId === member.id || relationship.toMemberId === member.id).map((relationship) => ({ relationship, person: members.find((person) => person.id === (relationship.fromMemberId === member.id ? relationship.toMemberId : relationship.fromMemberId)) })).filter((item) => item.person); const removeRelation = async (item) => { if (confirm(`Remove the relationship with ${item.person.fullName}?`)) { await deleteRelationship(item.relationship.id); window.location.reload() } }; const removeMember = async () => { if (confirm(`Delete ${member.fullName}? Connected descendants will be preserved through a Void node.`)) { await voidMember(member.id); window.location.reload() } }; return <motion.aside className="profile" initial={{ x: 360 }} animate={{ x: 0 }} exit={{ x: 360 }}><button className="close" onClick={close}><X /></button><Avatar member={member} large /><p className="eyebrow">{member.isRootPerson ? 'SELF · PRIMARY PERSON' : 'FAMILY MEMBER'}</p><h2>{member.preferredName || member.fullName}</h2>{kinship && <div className="kinship-badge"><span>Relation to {root?.preferredName || root?.fullName || 'Self'}</span><b>{kinship.term}</b><small>{kinship.english}</small></div>}{member.hometown && <p className="hint">{member.hometown}</p>}{linked.length > 0 && <><h3>Relationships</h3><div className="linked relationship-list">{linked.map((item) => <span key={item.relationship.id}><Avatar member={item.person} /><b>{item.person.preferredName || item.person.fullName}</b><small>{item.relationship.label || item.relationship.type}</small><button className="remove-relation" onClick={() => removeRelation(item)}>Remove</button></span>)}</div></>}<button className="primary full" onClick={edit}><Pencil size={16} /> Edit profile</button>{!member.isRootPerson && <button className="delete-member" onClick={removeMember}>Delete member</button>}</motion.aside> }
