const relationshipFromLabel = (memberId, relatedId, label) => { const rule = relationRule(label); return { type: rule.type, label: label.trim(), fromMemberId: rule.relatedIs === 'parent' ? relatedId : memberId, toMemberId: rule.relatedIs === 'parent' ? memberId : relatedId } }
function MemberDialogLabelOnly({ member, groupId, members, done }) { const [form, setForm] = useState({ ...blankMember, ...member }); const [relatedId, setRelatedId] = useState(''); const [label, setLabel] = useState(''); const [busy, setBusy] = useState(false); const set = (key, value) => setForm((current) => ({ ...current, [key]: value })); const submit = async (event) => { event.preventDefault(); if (!form.fullName.trim()) return; setBusy(true); try { const saved = await saveMember({ ...form, familyGroupId: groupId }, member?.id); const memberId = member?.id || saved.id; if (relatedId && label.trim()) await saveRelationship({ familyGroupId: groupId, ...relationshipFromLabel(memberId, relatedId, label) }); done() } finally { setBusy(false) } }; const choices = members.filter((person) => person.id !== member?.id); return <Dialog title={member ? `Edit ${member.fullName}` : 'Add family member'} close={done} wide><form className="form member-form" onSubmit={submit}><div className="member-essentials"><label>Full name *<input autoFocus required value={form.fullName} onChange={(e) => set('fullName', e.target.value)} /></label><label>Location<input value={form.hometown} onChange={(e) => set('hometown', e.target.value)} placeholder="Optional" /></label></div>{choices.length > 0 && <fieldset><legend>Add relationship</legend><div className="form-grid"><label>Related family member<select value={relatedId} onChange={(e) => setRelatedId(e.target.value)}><option value="">Choose a person</option>{choices.map((person) => <option key={person.id} value={person.id}>{person.fullName}</option>)}</select></label><label>Relationship label<input list="label-only-relation-catalog" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Father, Wife, Kaka…" /><datalist id="label-only-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label></div></fieldset>}<details className="optional-details"><summary>Optional details <span>Names, dates, contact information and notes</span></summary><div className="optional-content"><div className="form-grid"><label>Preferred name<input value={form.preferredName} onChange={(e) => set('preferredName', e.target.value)} /></label><label>Nickname<input value={form.nickname} onChange={(e) => set('nickname', e.target.value)} /></label><label>Birth date<input type="date" value={form.birthDate} onChange={(e) => set('birthDate', e.target.value)} /></label><label>Occupation<input value={form.occupation} onChange={(e) => set('occupation', e.target.value)} /></label></div></div></details><div className="dialog-actions"><button className="primary" disabled={busy}>{busy ? 'Saving…' : 'Save member'}</button></div></form></Dialog> }
MemberDialog = MemberDialogLabelOnly
function RelatedMemberPicker({ members, value, onChange }) { const selected = members.find((person) => person.id === value); const [query, setQuery] = useState(selected?.fullName || ''); const [open, setOpen] = useState(false); const matches = members.filter((person) => person.fullName.toLowerCase().includes(query.toLowerCase())); const choose = (person) => { setQuery(person.fullName); onChange(person.id); setOpen(false) }; return <div className="member-picker"><input value={query} onFocus={() => setOpen(true)} onChange={(event) => { setQuery(event.target.value); onChange(''); setOpen(true) }} placeholder="Search family member" />{open && <div className="member-picker-menu">{matches.length ? matches.map((person) => <button type="button" key={person.id} onMouseDown={(event) => event.preventDefault()} onClick={() => choose(person)}><Avatar member={person} />{person.fullName}</button>) : <span>No matching family member</span>}</div>}</div> }
function MemberDialogSearchableRelation({ member, groupId, members, done }) { const [form, setForm] = useState({ ...blankMember, ...member }); const [relatedId, setRelatedId] = useState(''); const [label, setLabel] = useState(''); const [busy, setBusy] = useState(false); const set = (key, value) => setForm((current) => ({ ...current, [key]: value })); const submit = async (event) => { event.preventDefault(); if (!form.fullName.trim()) return; setBusy(true); try { const saved = await saveMember({ ...form, familyGroupId: groupId }, member?.id); const memberId = member?.id || saved.id; if (relatedId && label.trim()) await saveRelationship({ familyGroupId: groupId, ...relationshipFromLabel(memberId, relatedId, label) }); done() } finally { setBusy(false) } }; const choices = members.filter((person) => person.id !== member?.id); return <Dialog title={member ? `Edit ${member.fullName}` : 'Add family member'} close={done} wide><form className="form member-form" onSubmit={submit}><div className="member-essentials"><label>Full name *<input autoFocus required value={form.fullName} onChange={(e) => set('fullName', e.target.value)} /></label><label>Location<input value={form.hometown} onChange={(e) => set('hometown', e.target.value)} placeholder="Optional" /></label></div>{choices.length > 0 && <fieldset><legend>Add relationship</legend><div className="form-grid"><label>Related family member<RelatedMemberPicker members={choices} value={relatedId} onChange={setRelatedId} /></label><label>Relationship label<input list="searchable-relation-catalog" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Papa, Spouse, Kaka…" /><datalist id="searchable-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label></div></fieldset>}<details className="optional-details"><summary>Optional details <span>Names, dates, contact information and notes</span></summary><div className="optional-content"><div className="form-grid"><label>Preferred name<input value={form.preferredName} onChange={(e) => set('preferredName', e.target.value)} /></label><label>Nickname<input value={form.nickname} onChange={(e) => set('nickname', e.target.value)} /></label></div></div></details><div className="dialog-actions"><button className="primary" disabled={busy}>{busy ? 'Saving…' : 'Save member'}</button></div></form></Dialog> }
MemberDialog = MemberDialogSearchableRelation
function MemberDialogRelationshipAware({ member, groupId, members, done }) { const [form, setForm] = useState({ ...blankMember, ...member }); const [relatedId, setRelatedId] = useState(''); const [label, setLabel] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const set = (key, value) => setForm((current) => ({ ...current, [key]: value })); const chooseRelated = async (id) => { setRelatedId(id); setLabel(''); if (member && id) { const existing = await findRelationship(groupId, member.id, id); if (existing) setLabel(existing.label || '') } }; const submit = async (event) => { event.preventDefault(); if (!form.fullName.trim()) return setError('A full name is required.'); if (relatedId && !label.trim()) return setError('Add a relationship label for the selected family member.'); setBusy(true); try { const saved = await saveMember({ ...form, familyGroupId: groupId }, member?.id); const memberId = member?.id || saved.id; if (relatedId) await saveRelationship({ familyGroupId: groupId, ...relationshipFromLabel(memberId, relatedId, label) }); done() } catch { setError('Could not save this member. Please try again.') } finally { setBusy(false) } }; const choices = members.filter((person) => person.id !== member?.id && !person.isVoid); return <Dialog title={member ? `Edit ${member.fullName}` : 'Add family member'} close={done} wide><form className="form member-form" onSubmit={submit}>{error && <p className="error">{error}</p>}<div className="member-essentials"><label>Full name *<input autoFocus required value={form.fullName} onChange={(e) => set('fullName', e.target.value)} /></label><label>Location<input value={form.hometown} onChange={(e) => set('hometown', e.target.value)} placeholder="Optional" /></label></div>{choices.length > 0 && <fieldset><legend>Add relationship</legend><div className="form-grid"><label>Related family member<RelatedMemberPicker members={choices} value={relatedId} onChange={chooseRelated} /></label><label>Relationship label<input required={Boolean(relatedId)} list="aware-relation-catalog" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Papa, Spouse, Kaka…" /><datalist id="aware-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label></div></fieldset>}<details className="optional-details"><summary>Optional details <span>Names, dates, contact information and notes</span></summary><div className="optional-content"><div className="form-grid"><label>Preferred name<input value={form.preferredName} onChange={(e) => set('preferredName', e.target.value)} /></label><label>Nickname<input value={form.nickname} onChange={(e) => set('nickname', e.target.value)} /></label></div></div></details><div className="dialog-actions"><button className="primary" disabled={busy}>{busy ? 'Saving…' : 'Save member'}</button></div></form></Dialog> }
MemberDialog = MemberDialogRelationshipAware
function MemberDialogRelationshipManager({ member, groupId, members, done }) { const [form, setForm] = useState({ ...blankMember, ...member }); const [existing, setExisting] = useState([]); const [labels, setLabels] = useState({}); const [relatedId, setRelatedId] = useState(''); const [newLabel, setNewLabel] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const set = (key, value) => setForm((current) => ({ ...current, [key]: value })); useEffect(() => { if (!member) return; listMemberRelationships(groupId, member.id).then((items) => { setExisting(items); setLabels(Object.fromEntries(items.map((item) => [item.id, item.label || '']))) }) }, [member, groupId]); const submit = async (event) => { event.preventDefault(); if (!form.fullName.trim()) return setError('A full name is required.'); if (relatedId && !newLabel.trim()) return setError('Add a label for the new relationship.'); setBusy(true); try { const saved = await saveMember({ ...form, familyGroupId: groupId }, member?.id); const memberId = member?.id || saved.id; await Promise.all(existing.map((item) => updateRelationship(item.id, { label: labels[item.id]?.trim() || '', type: relationRule(labels[item.id]).type }))); if (relatedId) await saveRelationship({ familyGroupId: groupId, ...relationshipFromLabel(memberId, relatedId, newLabel) }); done() } catch { setError('Could not save this profile. Please try again.') } finally { setBusy(false) } }; const choices = members.filter((person) => person.id !== member?.id && !person.isVoid && !existing.some((item) => item.fromMemberId === person.id || item.toMemberId === person.id)); return <Dialog title={member ? `Edit ${member.fullName}` : 'Add family member'} close={done} wide><form className="form member-form" onSubmit={submit}>{error && <p className="error">{error}</p>}<div className="member-essentials"><label>Full name *<input autoFocus required value={form.fullName} onChange={(e) => set('fullName', e.target.value)} /></label><label>Location<input value={form.hometown} onChange={(e) => set('hometown', e.target.value)} placeholder="Optional" /></label></div>{member && existing.length > 0 && <fieldset><legend>Edit existing relationships</legend><div className="existing-relations">{existing.map((item) => { const otherId = item.fromMemberId === member.id ? item.toMemberId : item.fromMemberId; const other = members.find((person) => person.id === otherId); return <label key={item.id}>{other?.fullName || 'Family member'}<input list="existing-relation-catalog" value={labels[item.id] || ''} onChange={(e) => setLabels({ ...labels, [item.id]: e.target.value })} /></label> })}<datalist id="existing-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></div></fieldset>}{choices.length > 0 && <fieldset><legend>Add new relationship</legend><div className="form-grid"><label>Related family member<RelatedMemberPicker members={choices} value={relatedId} onChange={setRelatedId} /></label><label>Relationship label<input required={Boolean(relatedId)} list="new-relation-catalog" value={newLabel} onChange={(e) => setNewLabel(e.target.value)} placeholder="Papa, Spouse, Kaka…" /><datalist id="new-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label></div></fieldset>}<details className="optional-details"><summary>Optional details <span>Names, dates, contact information and notes</span></summary><div className="optional-content"><div className="form-grid"><label>Preferred name<input value={form.preferredName} onChange={(e) => set('preferredName', e.target.value)} /></label><label>Nickname<input value={form.nickname} onChange={(e) => set('nickname', e.target.value)} /></label></div></div></details><div className="dialog-actions"><button className="primary" disabled={busy}>{busy ? 'Saving…' : 'Save member'}</button></div></form></Dialog> }
MemberDialog = MemberDialogRelationshipManager
function RelationshipOverlay() {
  const [selected, setSelected] = useState(null); const [name, setName] = useState(''); const [label, setLabel] = useState(''); const [role, setRole] = useState('child'); const [busy, setBusy] = useState(false)
  useEffect(() => { const open = (event) => { setSelected(event.detail.member); setName(''); setLabel(''); setRole('child') }; window.addEventListener('add-related-member', open); return () => window.removeEventListener('add-related-member', open) }, [])
  const save = async (event) => { event.preventDefault(); if (!name.trim() || !selected) return; setBusy(true); try { const person = await saveMember({ fullName: name.trim(), familyGroupId: selected.familyGroupId, archived: false }); const isParent = role === 'parent'; await saveRelationship({ familyGroupId: selected.familyGroupId, type: role === 'spouse' ? 'spouse' : 'parent_child', label: label.trim(), fromMemberId: isParent ? person.id : selected.id, toMemberId: isParent ? selected.id : person.id }); setSelected(null); window.location.reload() } finally { setBusy(false) } }
  if (!selected) return null
  return <Dialog title={`Add a relation to ${selected.fullName}`} close={() => setSelected(null)}><form className="form" onSubmit={save}><label>Person’s full name *<input autoFocus required value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Ramesh Patel" /></label><label>They are {selected.fullName}’s<select value={role} onChange={(e) => setRole(e.target.value)}><option value="parent">Parent</option><option value="child">Child</option><option value="spouse">Spouse</option></select></label><label>Relationship label<input list="quick-relation-catalog" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="e.g. Father, Kaka, Wife" /><datalist id="quick-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label><button className="primary" disabled={busy}>{busy ? 'Adding…' : 'Add related person'}</button></form></Dialog>
}
function RelationshipOverlayLabelOnly() { const [selected, setSelected] = useState(null); const [name, setName] = useState(''); const [label, setLabel] = useState(''); const [busy, setBusy] = useState(false); useEffect(() => { const open = (event) => { setSelected(event.detail.member); setName(''); setLabel('') }; window.addEventListener('add-related-member', open); return () => window.removeEventListener('add-related-member', open) }, []); const save = async (event) => { event.preventDefault(); if (!name.trim() || !label.trim()) return; setBusy(true); try { const person = await saveMember({ fullName: name.trim(), familyGroupId: selected.familyGroupId, archived: false }); await saveRelationship({ familyGroupId: selected.familyGroupId, ...relationshipFromLabel(selected.id, person.id, label) }); setSelected(null); window.location.reload() } finally { setBusy(false) } }; if (!selected) return null; return <Dialog title={`Add a relation to ${selected.fullName}`} close={() => setSelected(null)}><form className="form" onSubmit={save}><label>Person’s full name *<input autoFocus required value={name} onChange={(e) => setName(e.target.value)} /></label><label>Relationship label *<input required list="quick-label-only-catalog" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Father, Wife, Kaka…" /><datalist id="quick-label-only-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label><button className="primary" disabled={busy}>{busy ? 'Adding…' : 'Add related person'}</button></form></Dialog> }
RelationshipOverlay = RelationshipOverlayLabelOnly
function RelationshipDetailOverlay() {
  const [relation, setRelation] = useState(null); const [editing, setEditing] = useState(false); const [label, setLabel] = useState(''); const [type, setType] = useState('parent_child'); const [busy, setBusy] = useState(false)
  useEffect(() => { const open = async (event) => { const loaded = await getRelationship(event.detail); if (loaded) { setRelation(loaded); setLabel(loaded.label || ''); setType(loaded.type || 'parent_child'); setEditing(false) } }; window.addEventListener('open-relationship-detail', open); return () => window.removeEventListener('open-relationship-detail', open) }, [])
  const remove = async () => { if (!confirm('Delete this relationship? The family members will remain.')) return; setBusy(true); await deleteRelationship(relation.id); window.location.reload() }
  const save = async (event) => { event.preventDefault(); setBusy(true); await updateRelationship(relation.id, { label: label.trim(), type }); window.location.reload() }
  if (!relation) return null
  return <Dialog title="Relationship details" close={() => setRelation(null)}><form className="form" onSubmit={save}><div className="relation-members"><b>{relation.fromMemberName}</b><span>↔</span><b>{relation.toMemberName}</b></div>{editing ? <><label>Relationship label<input autoFocus list="edge-relation-catalog" value={label} onChange={(e) => setLabel(e.target.value)} /><datalist id="edge-relation-catalog">{relationCatalog.map((item) => <option key={item.id} value={item.term}>{item.english}</option>)}</datalist></label><label>Connection type<select value={type} onChange={(e) => setType(e.target.value)}><option value="parent_child">Parent / child</option><option value="spouse">Spouse</option></select></label></> : <><p className="relation-detail-label">{relation.label || 'Unlabelled relationship'}</p><p className="hint">{relation.type === 'spouse' ? 'Spouse connection' : 'Parent / child connection'}</p></>}<div className="dialog-actions">{editing ? <><button type="button" className="danger" onClick={remove}>Delete relationship</button><button className="primary" disabled={busy}>Save relationship</button></> : <><button type="button" className="danger" onClick={remove}>Delete relationship</button><button type="button" className="primary" onClick={() => setEditing(true)}>Edit relationship</button></>}</div></form></Dialog>
}
function PositionPersistence() { useEffect(() => { const save = ({ detail }) => { saveMember({ position: detail.position }, detail.id).catch(() => {}) }; window.addEventListener('move-family-member', save); return () => window.removeEventListener('move-family-member', save) }, []); return null }
function Loading({ label }) { return <div className="loading"><span className="loader" />{label}</div> }
function Empty({ onClick, text = 'No branches yet. Start with the family you know best.' }) { return <div className="empty"><Users size={34} /><h3>There’s room for your story.</h3><p>{text}</p><button className="primary" onClick={onClick}><Plus size={17} /> Get started</button></div> }
export default App
